class Employee { protected int employeeId; protected String employeeName; protected double salary; Employee(int employeeId,String employeeName,double salary){this.employeeId=employeeId;this.employeeName=employeeName;this.salary=salary;} void displayEmployee(){System.out.println(employeeId+" "+employeeName+" "+salary);} }
class Pharmacist extends Employee { private String licenseNo; Pharmacist(int employeeId,String employeeName,double salary,String licenseNo){super(employeeId,employeeName,salary);this.licenseNo=licenseNo;} void displayPharmacist(){displayEmployee();System.out.println(licenseNo);} }
public class Q13_SingleInheritanceMain { public static void main(String[] a){new Pharmacist(1,"Riya",50000,"LIC9").displayPharmacist();} }
